(function(){
const text=(el,name)=>Array.from(el.getElementsByTagNameNS('*',name));
function xml(s){if(s.length>30000000)throw Error('A worksheet is too large. Use a workbook under 10 MB.');let d=new DOMParser().parseFromString(s,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('Could not read workbook XML.');return d;}
async function readWorkbook(file){if(file.size>10000000)throw Error('Please upload an XLSX workbook under 10 MB.');let z=await JSZip.loadAsync(await file.arrayBuffer());async function get(path){let entry=z.file(path);if(!entry)throw Error('Workbook part missing: '+path);return xml(await entry.async('string'));}
let shared=z.file('xl/sharedStrings.xml')?text(await get('xl/sharedStrings.xml'),'si').map(si=>text(si,'t').map(t=>t.textContent).join('')):[];
let rels=await get('xl/_rels/workbook.xml.rels'),paths={};for(let r of text(rels,'Relationship')){let p=r.getAttribute('Target');paths[r.getAttribute('Id')]=p.startsWith('/')?p.slice(1):'xl/'+p.replace(/^\.\//,'');}
let workbook=await get('xl/workbook.xml'),result={};for(let s of text(workbook,'sheet')){let rid=s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||s.getAttribute('r:id');let name=s.getAttribute('name');if(!['Applications','Territories','Existing stores'].includes(name))continue;let doc=await get(paths[rid]),rows=[];for(let row of text(doc,'row')){let values=[];for(let c of text(row,'c')){let addr=c.getAttribute('r')||'',letters=addr.match(/[A-Z]+/)?.[0]||'A',col=0;for(let ch of letters)col=col*26+ch.charCodeAt(0)-64;let type=c.getAttribute('t'),v=text(c,'v')[0]?.textContent;values[col-1]=type==='s'?shared[Number(v)]:type==='inlineStr'?text(c,'t').map(t=>t.textContent).join(''):v===undefined?null:type==='str'?v:type==='b'?v==='1':Number.isFinite(Number(v))?Number(v):v;}if(values.some(v=>v!==null&&v!==undefined&&v!==''))rows.push({row:Number(row.getAttribute('r')),values});}result[name]=rows;}return result;}
function importRows(sheets,includeExamples=false,fixedStores=[]){let warnings=[],apps=[],territories=[];let rows=sheets.Applications;if(!rows)throw Error('The workbook needs an Applications sheet.');let h=rows.find(r=>r.values.includes('Application ID'));if(!h)throw Error('Could not find the Application ID header. Use the supplied template.');const hasExample=rs=>rs.some(r=>r.row===1&&r.values.some(v=>/row\s*3/i.test(String(v))&&/example/i.test(String(v))));let skipAppExample=!includeExamples&&hasExample(rows);let skipTerritoryExample=!includeExamples&&hasExample(sheets.Territories||[]);let map={};for(let [k,v] of Object.entries(Engine.labels)){map[k]=h.values.indexOf(v);if(map[k]<0)warnings.push('Missing application column: '+v);}
for(let row of rows.filter(r=>r.row>h.row)){if(skipAppExample&&row.row===3)continue;let raw={};for(let k of Engine.fields)raw[k]=map[k]>=0?row.values[map[k]]??null:null;if(!Object.values(raw).some(v=>v!==null&&v!==''))continue;apps.push(Engine.normalize(raw,'sheet-row-'+row.row));}
let tr=sheets.Territories||[],th=tr.find(r=>r.values.includes('Territory ID'));if(!th)warnings.push('Territories sheet or header missing. Applications will need territory review.');else{const names=['Territory ID','City','State','Pin codes covered','City tier','Open slots','Priority'];for(let row of tr.filter(r=>r.row>th.row)){if(skipTerritoryExample&&row.row===3)continue;const vals=names.map(n=>row.values[th.values.indexOf(n)]??null);if(!vals.some(v=>v!==null&&v!==''))continue;let [id,city,state,pinList,tier,slots,priority]=vals;let pins=String(pinList??'').split(/[,;\n]/).map(p=>p.trim()).filter(Boolean);let issues=[];for(let [i,v] of vals.entries())if(v===null||v==='')issues.push('Missing '+names[i]);if(pins.some(p=>!/^\d{6}$/.test(p)))issues.push('Invalid pin code');let slotNum=slots===null||slots===''?null:Number(slots);if(!Number.isInteger(slotNum)||slotNum<0)issues.push('Invalid open slots');if(!['High','Medium','Low'].includes(priority))issues.push('Invalid priority');if(!Engine.cities[city]||Engine.cities[city]?.[1]!==tier||state!=='Karnataka'||pins.some(p=>!p.startsWith(Engine.cities[city]?.[0]||'INVALID')))issues.push('City, tier, state or pin prefix conflict');territories.push({id:String(id||'Missing ID row '+row.row),city,state,pins,tier,slots:slotNum,priority,issues});}}
for(let t of territories)if(territories.filter(x=>x.id===t.id).length>1)t.issues.push('Duplicate territory ID');
if(skipAppExample||skipTerritoryExample)warnings.push('Row 3 template examples excluded. Enable “Include row 3 examples” to assess the supplied sample.');if(fixedStores.length){let sr=sheets['Existing stores']||[],sh=sr.find(r=>r.values.includes('Store ID')),actual=sh?sr.filter(r=>r.row>sh.row).map(r=>r.values):[];if(actual.length!==fixedStores.length||fixedStores.some(f=>!actual.some(v=>String(v[0])===f.id&&v[1]===f.city&&String(v[2])===f.pin&&Number(v[3])===f.year)))warnings.push('Uploaded existing stores differ from the fixed case list. The protected fixed store list is used; uploaded changes are not adopted.');}if(!apps.length)warnings.push('No applicant records found below the example row.');return {apps,territories,warnings};}
window.WorkbookReader={readWorkbook,importRows};
})();
